<?php
if(!defined('ABSPATH'))exit;
add_action('init',function(){if(get_option('bhc_catalog_image_legacy_emersun_v255'))return;$items=[['sku'=>'BHC-EMERSUN-EF10','src'=>__DIR__.'/emersun-ef10-source.png','rel'=>'bhc-image-references/emersun-ef10.png','label'=>'Emersun EF10'],['sku'=>'BHC-EMERSUN-EF11','src'=>__DIR__.'/emersun-ef11-source.png','rel'=>'bhc-image-references/emersun-ef11.png','label'=>'Emersun EF11'],['sku'=>'BHC-EMERSUN-EF12','src'=>__DIR__.'/emersun-ef12-source.png','rel'=>'bhc-image-references/emersun-ef12.png','label'=>'Emersun EF12'],['sku'=>'BHC-EMERSUN-EF13','src'=>__DIR__.'/emersun-ef13-source.png','rel'=>'bhc-image-references/emersun-ef13.png','label'=>'Emersun EF13'],['sku'=>'BHC-EMERSUN-UN-55','src'=>__DIR__.'/emersun-un55-source.png','rel'=>'bhc-image-references/emersun-un55.png','label'=>'Emersun UN-55']];$out=[];foreach($items as $it){$id=wc_get_product_id_by_sku($it['sku']);$file=ABSPATH.'wp-content/uploads/'.$it['rel'];$ok=false;$aid=0;if($id&&is_readable($it['src'])){$im=@imagecreatefrompng($it['src']);if($im){wp_mkdir_p(dirname($file));$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=max(1,(int)round($w*$scale));$nh=max(1,(int)round($h*$scale));$c=imagecreatetruecolor($nw,$nh);imagealphablending($c,false);imagesavealpha($c,true);$z=imagecolorallocatealpha($c,0,0,0,127);imagefill($c,0,0,$z);imagecopyresampled($c,$im,0,0,0,0,$nw,$nh,$w,$h);imagepng($c,$file,6);imagedestroy($c);imagedestroy($im);$ok=is_readable($file);}}if($ok){$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>$it['label'].' اختصاصی 4K شفاف - نیازمند تطبیق مدل','post_status'=>'inherit','post_parent'=>$id],$file,$id);if($aid&&!is_wp_error($aid)){update_post_meta($aid,'_wp_attached_file',$it['rel']);$q=@getimagesize($file);wp_update_attachment_metadata($aid,['width'=>$q[0]??4096,'height'=>$q[1]??4096,'file'=>$it['rel'],'sizes'=>[]]);set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','product_specific_generated_candidate');update_post_meta($id,'_bhc_image_status','generated_4k_transparent_candidate');update_post_meta($id,'_bhc_image_long_edge',max((int)($q[0]??0),(int)($q[1]??0)));update_post_meta($id,'_bhc_image_featured_verified','yes');update_post_meta($id,'_bhc_image_reference_url',wp_get_attachment_url($aid));update_post_meta($id,'_bhc_image_reference_evidence','تصویر اختصاصی مدل با پرامپت محصول‌محور تولید و به SKU صحیح متصل شد؛ چون منبع مدل قدیمی هنوز کامل تطبیق نشده، تصویر تا کنترل نهایی به‌عنوان candidate علامت‌گذاری شده است.');update_post_meta($id,'_bhc_image_reference_checked_at','2026-11-20');}}$out[$it['label']]=['id'=>$id,'ok'=>$ok,'attachment'=>$aid];}update_option('bhc_catalog_image_legacy_emersun_v255',['items'=>$out,'at'=>current_time('mysql')],false);},255);
